<?php
$adminTitle='Porositë';$adminActive='orders';require __DIR__.'/_header.php';
$allowed=['pending','processing','completed','cancelled'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if(in_array($status,$allowed,true)){$stmt=$db->prepare('UPDATE orders SET status=? WHERE id=?');$stmt->bind_param('si',$status,$id);$stmt->execute();flash('success','Statusi i porosisë u ndryshua.');}redirect('admin/orders.php');}
$orders=$db->query('SELECT o.*,COUNT(oi.id) item_count FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.id GROUP BY o.id ORDER BY o.created_at DESC');
?>
<div class="table-card"><div class="table-wrap"><table class="data-table"><thead><tr><th>ID / Data</th><th>Klienti</th><th>Dërgesa</th><th>Produkte</th><th>Totali</th><th>Statusi</th></tr></thead><tbody><?php while($o=$orders->fetch_assoc()): ?><tr><td><strong>#<?= $o['id'] ?></strong><br><small class="muted"><?= date('d.m.Y H:i',strtotime($o['created_at'])) ?></small></td><td><strong><?= e($o['customer_name']) ?></strong><br><small><?= e($o['email']) ?><br><?= e($o['phone']) ?></small></td><td><small><?= nl2br(e($o['address'])) ?></small></td><td><?= $o['item_count'] ?></td><td><strong><?= money((float)$o['total']) ?></strong></td><td><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="id" value="<?= $o['id'] ?>"><select name="status" onchange="this.form.submit()"><?php foreach($allowed as $status): ?><option value="<?= $status ?>" <?= $o['status']===$status?'selected':'' ?>><?= ucfirst($status) ?></option><?php endforeach; ?></select></form></td></tr><?php endwhile; ?></tbody></table></div></div>
